import{c as e,Q as s,j as i,m as l}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"重启我的个人博客","description":"","frontmatter":{},"headers":[],"relativePath":"blog/rebuild-this-site.md","filePath":"blog/rebuild-this-site.md","lastUpdated":null}'),t={name:"blog/rebuild-this-site.md"};function n(o,a,p,r,d,c){return s(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="重启我的个人博客" tabindex="-1">重启我的个人博客 <a class="header-anchor" href="#重启我的个人博客" aria-label="Permalink to &quot;重启我的个人博客&quot;">​</a></h1><div class="spring-meta"><span>site</span><span>vitepress</span><span>rebuild</span></div><h2 id="起点" tabindex="-1">起点 <a class="header-anchor" href="#起点" aria-label="Permalink to &quot;起点&quot;">​</a></h2><p>旧版本博客已经有了雏形，也积累了一些学习笔记。但它的问题也很明显：内容过时、导航混杂、视觉上更像课程笔记站，而不是一个可以长期维护的个人技术入口。</p><p>这次重构的目标不是追求复杂，而是先把基础打稳：</p><ul><li>首页能清楚说明我是谁、写什么、做什么。</li><li>Notes 和 Blog 分开，避免所有内容堆在同一层。</li><li>Projects 有独立入口，方便和 GitHub 主页互相引用。</li><li>视觉上更清爽，有个人气质，但不喧宾夺主。</li></ul><h2 id="为什么选择-vitepress" tabindex="-1">为什么选择 VitePress <a class="header-anchor" href="#为什么选择-vitepress" aria-label="Permalink to &quot;为什么选择 VitePress&quot;">​</a></h2><p>VitePress 适合技术博客和文档：</p><ul><li>保留 Markdown 写作体验。</li><li>底层是 Vue，后续可以自定义组件。</li><li>静态部署简单，适合 GitHub Pages。</li><li>默认文档能力完整，包括导航、搜索、目录和代码高亮。</li></ul><h2 id="新结构" tabindex="-1">新结构 <a class="header-anchor" href="#新结构" aria-label="Permalink to &quot;新结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>  index.md</span></span>
<span class="line"><span>  notes/</span></span>
<span class="line"><span>  blog/</span></span>
<span class="line"><span>  projects/</span></span>
<span class="line"><span>  about.md</span></span></code></pre></div><p>其中：</p><ul><li><code>notes/</code> 放可复用技术笔记。</li><li><code>blog/</code> 放完整文章和复盘。</li><li><code>projects/</code> 放项目展示。</li><li><code>about.md</code> 放个人介绍和链接。</li></ul><h2 id="后续计划" tabindex="-1">后续计划 <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;后续计划&quot;">​</a></h2><ol><li>先把 GitHub profile 和博客首页打通。</li><li>再迁移旧站里仍有价值的技术笔记。</li><li>每次迁移顺手更新过时内容。</li><li>最后再考虑把文章拆成更适合其他平台的短内容。</li></ol><p>先把自己的知识库打扫干净，再考虑对外分发。</p>`,16)])])}const b=e(t,[["render",n]]);export{u as __pageData,b as default};
